      "source": "// DSU (disjoint set union) — contest version.\n// Elements 0..n-1. Union by size + path compression: amortized O(alpha(n)) per op, O(n) memory.\n// find() recurses; with union by size the tree depth is <= log2(n), so recursion is safe.\n// C++17, headers <utility> <vector>. Interface: find(x), unite(a,b) -> merged?, same(a,b), size_of(x).\n#include <utility>\n#include <vector>\nstruct DSU {\n  std::vector<int> p;  // p[x] < 0: x is a root and -p[x] is its set size; otherwise parent\n  explicit DSU(int n = 0) : p(n, -1) {}\n  int find(int x) { return p[x] < 0 ? x : p[x] = find(p[x]); }\n  bool unite(int a, int b) {\n    a = find(a), b = find(b);\n    if (a == b) return false;\n    if (p[a] > p[b]) std::swap(a, b);  // a is the larger tree\n    p[a] += p[b], p[b] = a;\n    return true;\n  }\n  bool same(int a, int b) { return find(a) == find(b); }\n  int size_of(int x) { return -p[find(x)]; }\n};\n\n// ---- example main (stdin/stdout) — protocol follows Library Checker \"Union Find\":\n// first line: N Q; then Q lines \"t u v\": t=0 unite(u,v); t=1 print 1 if same(u,v) else 0.\n#include <cstdio>\nint main() {\n  int n, q;\n  if (std::scanf(\"%d %d\", &n, &q) != 2) return 0;\n  DSU d(n);\n  while (q--) {\n    int t, u, v;\n    std::scanf(\"%d %d %d\", &t, &u, &v);\n    if (t == 0) d.unite(u, v);\n    else std::printf(\"%d\\n\", d.same(u, v) ? 1 : 0);\n  }\n  return 0;\n}\n",
