      "source": "// Fenwick tree (BIT) — contest version. Point add, prefix / range sum; 0-based, half-open [l, r).\n// O(log n) per op, O(n) memory. Sums must fit in T (long long by default: |sum| < 9.2e18).\n// C++17, header <vector>. Interface: add(i,d), prefix(r) = sum a[0..r), sum(l,r) = sum a[l..r).\n#include <vector>\ntemplate <class T = long long>\nstruct BIT {\n  int n;\n  std::vector<T> t;  // 1-based internally, t[0] unused\n  explicit BIT(int n = 0) : n(n), t(n + 1) {}\n  void add(int i, T d) { for (++i; i <= n; i += i & -i) t[i] += d; }\n  T prefix(int r) const { T s = 0; for (; r > 0; r -= r & -r) s += t[r]; return s; }\n  T sum(int l, int r) const { return prefix(r) - prefix(l); }\n};\n\n// ---- example main (stdin/stdout) — protocol follows Library Checker \"Point Add Range Sum\":\n// first line: N Q; second line: a_0..a_{N-1}; then Q lines: \"0 p x\" a[p] += x; \"1 l r\" print sum a[l..r).\n#include <cstdio>\nint main() {\n  int n, q;\n  if (std::scanf(\"%d %d\", &n, &q) != 2) return 0;\n  BIT<long long> b(n);\n  for (int i = 0; i < n; i++) {\n    long long x;\n    std::scanf(\"%lld\", &x);\n    b.add(i, x);\n  }\n  while (q--) {\n    int t;\n    std::scanf(\"%d\", &t);\n    if (t == 0) {\n      int p;\n      long long x;\n      std::scanf(\"%d %lld\", &p, &x);\n      b.add(p, x);\n    } else {\n      int l, r;\n      std::scanf(\"%d %d\", &l, &r);\n      std::printf(\"%lld\\n\", b.sum(l, r));\n    }\n  }\n  return 0;\n}\n",
